package com.harish.student_management.service;
import com.harish.student_management.dto.*; import com.harish.student_management.dto.AchievementDtos.Request; import com.harish.student_management.dto.AchievementDtos.Response; import com.harish.student_management.entity.*; import com.harish.student_management.exception.ResourceNotFoundException; import com.harish.student_management.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class AchievementServiceImpl implements AchievementService { private final StudentAchievementRepository repo; private final StudentRepository students; private final TeacherRepository teachers; private final TeacherAccessService access; private final NotificationPublisher notifications; public Response create(Request r,Long teacherId){Student s=students.findById(r.getStudentId()).orElseThrow(()->new ResourceNotFoundException("Student not found"));Teacher t=teacherId==null?null:teachers.findById(teacherId).orElseThrow(()->new ResourceNotFoundException("Teacher not found"));if(t!=null&&s.getSection()!=null)access.validateTeacherAccessToClass(t.getId(),s.getSection().getClassEntity().getId());String type=r.getAchievementType().toUpperCase();if(!Set.of("ANNUAL_DAY","SPORTS_DAY","CULTURAL_EVENT","COMPETITION","SCIENCE_FAIR","ACHIEVEMENT","STUDENT_OF_THE_DAY").contains(type))throw new IllegalArgumentException("Unsupported achievement type");StudentAchievement a=repo.save(StudentAchievement.builder().student(s).createdByTeacher(t).achievementType(type).title(r.getTitle()).description(r.getDescription()).achievementDate(r.getAchievementDate()).build());if(s.getParent()!=null){NotificationRequestDto n=new NotificationRequestDto();n.setType(NotificationTypes.EVENT);n.setTitle("Student achievement");n.setMessage(s.getName()+" received: "+r.getTitle());n.setRecipientRole("PARENTS");n.setRecipientId(s.getParent().getId());notifications.publish(n);}return map(a);} @Transactional(readOnly=true) public List<Response> student(Long id){return repo.findByStudentIdOrderByAchievementDateDesc(id).stream().map(this::map).toList();} private Response map(StudentAchievement a){return Response.builder().id(a.getId()).studentId(a.getStudent().getId()).studentName(a.getStudent().getName()).achievementType(a.getAchievementType()).title(a.getTitle()).description(a.getDescription()).achievementDate(a.getAchievementDate()).build();}}
